<style>.request-field span{display:block;margin-bottom:.4rem;font-size:.78rem;font-weight:600;color:#374151}.request-field em{font-style:normal;color:#9ca3af}.request-field input,.request-field select{width:100%;border:1px solid #e5e7eb;border-radius:.75rem;background:#f9fafb;color:#111827;padding:.68rem .75rem;font-size:.84rem;outline:0}.dark .request-field span{color:#e5e7eb}.dark .request-field input,.dark .request-field select{background:#13304f;border-color:#374151;color:#fff}</style>
<script>
document.getElementById('requestCurrency').innerHTML='<option value="NGN">Nigerian Naira (NGN)</option><option value="USDT">Tether (USDT)</option><option value="USDC">USD Coin (USDC)</option><option value="BTC">Bitcoin (BTC)</option><option value="ETH">Ethereum (ETH)</option><option value="SOL">Solana (SOL)</option>';
document.getElementById('collectionWallet').innerHTML='<option value="">Loading wallets…</option>';
fetch('../api/wallets/list.php',{credentials:'same-origin'}).then(r=>r.json()).then(d=>{if(!d.success)throw new Error(d.error||'Unable to load wallets');document.getElementById('collectionWallet').innerHTML=d.wallets.filter(w=>w.currency_code==='NGN'||w.kind==='crypto').map(w=>`<option value="${w.currency_code}">${w.name} (${w.currency_code})</option>`).join('')}).catch(e=>{document.getElementById('collectionWallet').innerHTML='<option value="">Wallets unavailable</option>';});
const requestSymbols={NGN:'₦',USD:'$',USDT:'₮'};function updatePreview(){const currency=document.getElementById('requestCurrency').value,amount=Number(document.getElementById('requestAmount').value||0),description=document.getElementById('requestDescription').value||'Payment request';document.getElementById('previewAmount').textContent=`${requestSymbols[currency]}${amount.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}`;document.getElementById('previewDescription').textContent=description;document.getElementById('previewExpiry').textContent=document.getElementById('requestExpiry').options[document.getElementById('requestExpiry').selectedIndex].text;}function createRequest(){const amount=Number(document.getElementById('requestAmount').value),payer=document.getElementById('payerName').value.trim();if(!amount||!payer){alert('Enter a payer name and an amount.');return}const token=Math.random().toString(36).slice(2,10).toUpperCase();document.getElementById('paymentLink').value=`https://flowwithlit.com/pay/REQ-${token}`;document.getElementById('requestForm').classList.add('hidden');document.getElementById('requestSuccess').classList.remove('hidden');localStorage.setItem('flowwithlitLastPaymentRequest',token);lucide.createIcons()}function copyPaymentLink(){navigator.clipboard.writeText(document.getElementById('paymentLink').value);alert('Payment link copied.')}function sharePaymentLink(){if(navigator.share){navigator.share({title:'Flowwithlit payment request',url:document.getElementById('paymentLink').value});}else{copyPaymentLink()}}['requestAmount','requestCurrency','requestDescription','requestExpiry'].forEach(id=>document.getElementById(id).addEventListener('input',updatePreview));updatePreview();
</script>
<script>
async function createRequest(){const amount=Number(document.getElementById('requestAmount').value),payer=document.getElementById('payerName').value.trim(),currency=document.getElementById('requestCurrency').value;if(!amount||!payer){alert('Enter a payer name and an amount.');return}try{const exp=document.getElementById('requestExpiry').value;const r=await fetch('../api/payment-links/create.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:`Payment request from ${payer}`,description:document.getElementById('requestDescription').value,amount,currency,expires_at:exp==='Never'?'':exp})}),d=await r.json();if(!r.ok||!d.success)throw new Error(d.error||'Unable to create request');document.getElementById('paymentLink').value=location.origin+d.url;document.getElementById('requestForm').classList.add('hidden');document.getElementById('requestSuccess').classList.remove('hidden');lucide.createIcons()}catch(e){alert(e.message)}}
</script>
